public:
    Chair() { cout << "Chair" << " "; }
    Chair(const Chair&) { cout << "CopyChair" << " "; }
    ~Chair() { cout << "~Chair" << " "; }
};
class Person {
    string name;
public:
    Person(string n): name(n) { cout << "Person" << " "; }
    Person(const Person& p): name(p.name) { cout << "CopyPerson" << " "; }
    ~Person() { cout << "~Person" << " "; }
};
class ChairofSuzume : public Chair, public Person {
public:
    ChairofSuzume(string name): Chair(), Person(name) { cout << "ChairofSuzume" << " "; }
    ~ChairofSuzume() { cout << "~ChairofSuzume" << " "; }
};
```
